def recall_strip(strip, need):
    if len(need) == 0:
        return []
    left = 0
    gap = len(need)
    counts = {}
    best = []
    for label in need:
        if label not in counts:
            counts[label] = 0
        counts[label] += 1
    for right in range(len(strip)):
        label = strip[right]
        if label in counts:
            if counts[label] > 0:
                gap -= 1
            counts[label] -= 1
        while gap == 0:
            if len(best) == 0 or right - left < best[1] - best[0]:
                best = [left, right]
            first = strip[left]
            if first in counts:
                counts[first] += 1
                if counts[first] > 0:
                    gap += 1
            left += 1
    return best

